/*
Archivo: tutorial_topics.dart
Propósito: Catálogo de temas de ayuda y guía educativa integrada de D&D 5e (2014) y uso de LA CRIPTA.
Creador: Alexander Camargo / Joshua Pérez Bullen
Modificaciones / Actualizaciones:
- 2026-10-12 [Joshua Pérez Bullen]: Guía base de temas de creación, combate y atributos.
- 2026-10-18 [Alexander Camargo]: Incorporación del tema de Hitos y Experiencia (XP) y mapeo para Control de Personajes e Hitos.
*/

class TutorialTopic {
  final String id, title, summary, detail;
  const TutorialTopic(this.id, this.title, this.summary, this.detail);
}

// Guía educativa 5e (2014): ejemplos ilustrativos, sin cálculos ejecutables.
const tutorialTopics = <TutorialTopic>[
  TutorialTopic(
      'intro',
      'D&D desde cero',
      'Una aventura compartida: tú decides qué intenta tu personaje y el grupo descubre qué sucede.',
      'Qué es D&D\nDungeons & Dragons, o D&D, es un juego de rol: un grupo imagina una aventura y decide qué hacen sus protagonistas. No necesitas actuar, usar disfraces ni hablar con una voz especial. Puedes decir «mi personaje pregunta al guardia por el camino» y eso ya es jugar.\n\nQuién participa\nCada jugador controla a un personaje: un aventurero con capacidades, equipo y una personalidad. Una persona ocupa el papel de Dungeon Master, abreviado DM. El DM describe el mundo, interpreta a sus habitantes y resuelve las consecuencias de las decisiones. Un personaje no jugador, o PNJ, es alguien que interpreta el DM, como una mercader o un bandido.\n\nCómo avanza una partida\nEl DM describe una situación. Los jugadores preguntan y deciden qué intentar. Si el resultado no está claro, las reglas y una tirada de dados ayudan a resolverlo. El DM cuenta qué sucede y comienza una nueva situación. Podéis conversar, explorar un bosque, investigar un misterio o combatir. No se trata de derrotar al DM: todos construyen la aventura.\n\nSesión, aventura y campaña\nUna sesión es una reunión para jugar. Una aventura es una historia con un problema que resolver y puede durar varias sesiones. Una campaña reúne aventuras conectadas, normalmente con los mismos personajes. La «mesa» es el grupo, aunque juguéis por internet y no compartáis una mesa física.\n\nQué necesitas para empezar\nUn grupo, alguien que dirija, una hoja de personaje y una forma de tirar dados, física o digital. Esta aplicación guarda hojas y organiza campañas; no sustituye la conversación ni dirige por vosotros. La guía usa D&D 5e de 2014. Empieza por Cómo jugar como jugador, después Características y modificadores y Tiradas. Si vas a dirigir, lee también Cómo dirigir como Dungeon Master.'),
  TutorialTopic(
      'player',
      'Cómo jugar como jugador',
      'Describe lo que intenta hacer tu personaje; el DM explica qué ocurre.',
      'Tu papel en el grupo\nControlas las decisiones de un aventurero. Pregunta qué ve, qué oye y qué sabe antes de elegir una acción. No necesitas conocer todas las reglas: describe primero lo que quieres conseguir y el DM te ayudará a identificar la tirada o el recurso necesario. Tu personaje puede equivocarse sin que tú estés jugando mal.\n\nEl ciclo de juego, paso a paso\n1. Escucha la escena: «Hay un puente de cuerda sobre un barranco».\n2. Pide información útil: «¿Parece firme? ¿Veo otra forma de cruzar?».\n3. Describe una intención y un método: «Voy a comprobar las cuerdas antes de pasar».\n4. El DM decide si hace falta una prueba y cuál. No toda acción exige dados.\n5. Comunica el resultado completo y escucha la consecuencia. Después decide qué hacer con la nueva información.\n\nUna conversación de ejemplo\nDM: «En la puerta de la torre hay una guardia».\nJugador: «Quiero entrar. Le explico que traemos noticias urgentes».\nDM: «Te escucha, pero duda. Haz una prueba de Carisma (Persuasión)».\nJugador: «Mi d20 da 12 y mi bonificador es +3: el total es 15».\nDM: «Acepta, pero os acompaña dentro».\nAquí la tirada resolvió la incertidumbre; la conversación dio contexto.\n\nCómo interpretar sin sentir vergüenza\nPuedes hablar en primera persona («busco a mi hermano») o narrar en tercera («mi personaje busca a su hermano»). Ambas formas sirven. No tienes que ser tan fuerte, convincente o inteligente como tu personaje para utilizar sus capacidades. Cuenta qué quiere y cómo lo intenta.\n\nQué hacer durante la sesión\nTen a mano tus PG, tus bonificadores y las capacidades que usas más. Anota objetos o pistas importantes. Escucha los turnos de los demás, comparte información y busca motivos para colaborar. Si no entiendes algo, pregunta. Antes de empezar, acordad el tono y los límites del grupo.\n\nEn esta aplicación\nCrea un personaje, revisa su hoja y únete a una campaña con el código del DM. Puedes consultar las hojas del grupo, pero solo editar la tuya. El icono de ayuda explica un campo; Saber más abre este tema. Volver desde la guía conserva el formulario abierto.'),
  TutorialTopic(
      'dm',
      'Cómo dirigir como Dungeon Master',
      'Presenta el mundo, interpreta sus habitantes y resuelve las acciones del grupo.',
      'Qué hace el DM\nEl Dungeon Master presenta lugares y situaciones, interpreta a los personajes no jugadores y aplica las reglas. Describe lo que los aventureros pueden percibir, sin contarles secretos que todavía no han descubierto. Su objetivo es facilitar una aventura interesante para todo el grupo, no ganar contra los jugadores.\n\nAntes de la primera sesión\nPregunta qué tipo de historia quiere el grupo: exploración, misterio, humor o aventuras heroicas. Acordad duración, horarios, límites de contenido y cómo pausar si alguien está incómodo. Ayuda a que los personajes tengan motivos para colaborar. Estas son recomendaciones de mesa, no requisitos mecánicos de las reglas.\n\nPrepara una situación pequeña\nPara empezar basta un lugar, un problema, algunos habitantes y una consecuencia. Ejemplo: un pueblo pierde suministros; unas ruinas cercanas esconden el origen; una exploradora conoce parte del camino. Piensa en pistas y varios modos de actuar. Evita preparar una única solución obligatoria: el grupo puede negociar, investigar o buscar otro acceso.\n\nDurante el juego\nDescribe la escena y pregunta «¿qué hacéis?». Escucha el objetivo y el método de cada jugador. Si una acción es posible y no tiene incertidumbre significativa, narra el resultado. Si existe una posibilidad relevante de fallo, determina la prueba, la dificultad y qué está en juego. Después interpreta el resultado y vuelve a dar una decisión al grupo.\n\nEjemplo de resolver una acción\nUna jugadora quiere trepar un muro. Pregunta por dónde sube y si usa una cuerda. Considera la superficie y las circunstancias; pide la prueba adecuada si hace falta. Si falla, la consecuencia puede ser no avanzar, hacer ruido o sufrir una caída cuando corresponda. Describe una consecuencia coherente, no una penalización arbitraria.\n\nReparte la atención\nPregunta a quien lleva tiempo sin participar qué quiere hacer. En combate respeta el orden de iniciativa. Si no recuerdas una regla, consulta el texto y comunica la decisión; no necesitas memorizarlo todo. Al terminar, pregunta qué disfrutaron y deja un breve resumen para la próxima sesión.\n\nEn esta aplicación\nCrear una campaña te convierte en su DM. Comparte el código, consulta al grupo y usa Estado de Personajes, Iniciativa y Combate y Notas Ocultas. Las etiquetas narrativas no aplican condiciones de juego automáticamente. El rastreador tampoco resuelve ataques ni guarda sus PG locales al salir.'),
  TutorialTopic(
      'rolls',
      'Tiradas, ventaja y desventaja',
      'Las tiradas resuelven acciones cuyo resultado es incierto.',
      'Cómo leer los dados\nLa letra d significa «dado». Un d20 tiene veinte caras; un d6 tiene seis. 2d6 significa tirar dos dados de seis caras y sumar sus resultados. 1d8 + 2 significa tirar un dado de ocho caras y añadir dos. El número que sale directamente en el dado se llama resultado natural.\n\nTres usos distintos del d20\nUna prueba de característica resuelve un intento, como investigar o trepar. Una tirada de ataque determina si alcanzas a un objetivo. Una tirada de salvación determina cómo resistes un efecto, como una trampa o un conjuro. Las tres usan un d20, pero no siempre los mismos bonificadores ni las mismas reglas.\n\nUna prueba completa\nEl DM pide la característica y, si corresponde, una habilidad. Tira un d20 y suma el bonificador indicado en tu hoja. El DM compara el total con una Clase de Dificultad, o CD: es el número que debes igualar o superar. Ejemplo ilustrativo: ante una CD 15, un 12 en el dado y un bonificador +3 dan 15; la prueba tiene éxito.\n\nNo sumes dos veces\nSi tu hoja ya muestra el total de una habilidad, ese número ya incorpora los bonificadores que correspondan. Usa ese total junto al d20. No vuelvas a sumar la misma característica o competencia. Si no hay competencia, la prueba sigue siendo posible salvo que una regla específica diga otra cosa.\n\nVentaja y desventaja\nCon ventaja, tira dos d20 y usa el mayor. Con desventaja, usa el menor. Después aplica tus bonificadores. Ejemplo: con ventaja salen 6 y 14; eliges 14 y sumas +3 para un total de 17. Tener varias fuentes de ventaja no añade más dados. Si hay ventaja y desventaja a la vez, se cancelan.\n\nQué significa sacar 1 o 20\nEn una tirada de ataque, un 1 natural falla y un 20 natural impacta y es crítico. Eso no convierte cualquier prueba de habilidad en fallo o éxito automático. Las salvaciones de muerte tienen reglas especiales. La tirada de daño utiliza los dados que indique el arma o el conjuro, no siempre un d20.\n\nCuándo tirar\nDescribe tu intención y espera a que el DM confirme la prueba. Los dados no hacen posible lo imposible ni sustituyen una conversación. La app muestra datos de tu hoja, pero el grupo debe tirar dados por su medio habitual.'),
  TutorialTopic(
      'combat',
      'Tu turno en combate',
      'La iniciativa establece el orden; decide cómo moverte y qué acción realizar.',
      'Ronda y turno\nEl combate organiza una situación rápida en turnos. Una ronda representa aproximadamente seis segundos dentro de la historia; durante ella cada participante tiene su turno. Aunque se resuelva por orden, los personajes actúan dentro de ese mismo intervalo de la ficción.\n\nCómo empieza\nEl DM establece quién participa y dónde está cada uno. Cada participante tira iniciativa y el DM ordena los resultados de mayor a menor. Si alguien está sorprendido, el DM aplica las reglas de sorpresa. No supongas que decir «ataco» te concede un turno gratuito antes de la iniciativa.\n\nQué puedes hacer en tu turno\nPuedes moverte hasta tu velocidad y realizar una acción. Puedes repartir el movimiento antes y después de la acción. Algunas acciones son Atacar, Lanzar un conjuro, Esquivar, Ayudar, Correr, Destrabarse u Ocultarse. Una acción puede permitir varios ataques si un rasgo lo indica; no todos los personajes los tienen.\n\nAcción adicional y reacción\nUna acción adicional solo está disponible cuando un rasgo, una capacidad o un conjuro dice que puedes usarla. No es una segunda acción genérica. Una reacción responde a un desencadenante, a menudo fuera de tu turno; tras usarla, recuperas la posibilidad de reaccionar al comienzo de tu siguiente turno.\n\nUn turno de ejemplo\nTu velocidad es 30 pies. Te mueves 10 pies hasta un enemigo, usas la acción Atacar y el DM confirma si impactas. Si impactas, tiras daño y se aplican sus efectos. Todavía podrías usar los 20 pies de movimiento restantes, pero alejarte de un enemigo puede provocar un ataque de oportunidad si se cumplen sus condiciones.\n\nAtacar y hacer daño son pasos separados\nElige el objetivo y confirma que está a tu alcance. Tira el ataque y compara el total con su CA. Si impactas, tira el daño del arma o conjuro. Ejemplo ilustrativo: 11 en el d20 más +5 da 16 contra CA 15; impacta. Si el daño es 1d8 + 3 y sale 4, causa 7 antes de otros efectos.\n\nTambién puedes proteger y ayudar\nNo todos los turnos necesitan causar daño. Puedes buscar cobertura, auxiliar a un aliado o intentar otra acción; explica tu objetivo al DM. Consulta el texto exacto de tus capacidades para conocer sus requisitos.\n\nEn esta aplicación\nEl DM registra iniciativa, pulsa Ordenar y ajusta los PG del rastreador. Reiniciar restaura esos PG y pone la iniciativa a cero. Salir de la pantalla pierde este registro local. No sustituye las tiradas ni modifica por sí solo la hoja del personaje.'),
  TutorialTopic(
      'race',
      'Raza',
      'Define el origen de tu personaje y parte de sus rasgos.',
      'Qué eliges aquí\nLa raza representa el origen fantástico del personaje, como humano, elfo o enano. En las reglas de 2014 proporciona rasgos mecánicos: bonificadores de características, velocidad, idiomas u otras capacidades. Un rasgo es una regla concreta del personaje; debes leer qué permite y cuándo funciona.\n\nNo es lo mismo que la clase\nPuedes imaginar un elfo guerrero o un humano mago. La raza describe parte de su origen; la clase describe su formación y capacidades de aventura. No determina si tu personaje es amable, valiente o desconfiado: esas decisiones pertenecen a su personalidad.\n\nCómo escoger si estás empezando\nPrimero imagina qué personaje te gustaría jugar. Después pide al DM que te muestre las opciones disponibles y comprueba sus rasgos. Algunas razas tienen subrazas con opciones adicionales. No elijas solo por un bonificador que aún no comprendes: pregunta qué hará ese rasgo durante una partida.\n\nEjemplo de la diferencia\nDos personajes pueden ser de la misma raza y tener clases diferentes. Compartirán ciertos rasgos de origen, pero usarán capacidades distintas cuando exploren, combatan o lancen magia. La historia puede explicar cómo aprendieron esas capacidades.\n\nEn esta aplicación\nElige una raza y, cuando aparezca, su subraza. Sus bonificadores se suman después de la compra de puntos. El semielfo recibe +2 en Carisma y tú eliges otras dos características distintas para recibir +1; no pueden ser Carisma. El elfo recibe competencia en Percepción y el semiorco en Intimidación. El semielfo elige dos habilidades. El enano de las colinas añade un punto de golpe en nivel 1 y el elfo del bosque tiene velocidad de 35 pies. Los demás rasgos, idiomas y capacidades se revisan con el DM.'),
  TutorialTopic(
      'subrace',
      'Subraza',
      'Es una variante de tu raza. Conserva sus rasgos y añade bonificadores o capacidades propios; no es una subclase. «Saber más» explica cada opción disponible.',
      'Qué es una subraza\nEs una variante dentro de una raza. Por ejemplo, enano es la raza y enano de las colinas es una subraza. Conservas los rasgos de la raza y añades los de la subraza según las reglas de 2014. No es una segunda raza ni una subclase: la subclase especializa tu clase de aventurero.\n\nCómo se suman los bonificadores\nPrimero repartes las puntuaciones base y después añades los aumentos de raza y subraza, una sola vez. Un enano recibe +2 en Constitución; si es de las colinas también recibe +1 en Sabiduría. Con CON base 13 y SAB base 12, termina con CON 15 y SAB 13. Son aumentos de puntuación: después se calculan los modificadores que utilizas al tirar.\n\nEnanos\nAmbas opciones conservan el +2 en Constitución de la raza. El enano de las colinas añade +1 en Sabiduría y un PG máximo adicional en nivel 1, más uno por cada nivel posterior. El enano de las montañas añade +2 en Fuerza y competencia con armaduras ligeras y medias. Esa competencia permite usarlas apropiadamente; no significa que aparezcan equipadas en tu inventario.\n\nElfos\nAmbas opciones conservan +2 en Destreza y la competencia racial en Percepción. El alto elfo añade +1 en Inteligencia y tiene elecciones de magia e idioma que debes completar con el DM. El elfo de los bosques añade +1 en Sabiduría y tiene una velocidad de 35 pies, además de sus otros rasgos. La subraza no obliga a elegir una clase concreta.\n\nMedianos y gnomos\nLos medianos conservan +2 en Destreza: piesligeros añade +1 en Carisma y fornido +1 en Constitución. Los gnomos conservan +2 en Inteligencia: de las rocas añade +1 en Constitución y de los bosques +1 en Destreza. Revisa también sus rasgos específicos con el DM, pues un bonificador de atributo no resume todas sus capacidades.\n\nCómo elegir en la aplicación\nEl selector aparece solo cuando la raza tiene subrazas disponibles. Escoge la variante que quieres jugar y revisa el resumen: sus bonificadores se aplican automáticamente. La creación incorpora los PG iniciales del enano de las colinas y la velocidad del elfo de los bosques. Las elecciones de conjuros, idiomas, equipo y demás rasgos se completan con el DM; al subir de nivel, revisa también el PG adicional del enano de las colinas. Si cambias de raza, comprueba la nueva subraza que muestra el selector.\n\nSi no aparece este campo\nAlgunas razas del catálogo no tienen subrazas seleccionables. No necesitas inventar una para continuar. El semielfo, por ejemplo, elige sus bonificadores y habilidades en Atributos base. Antes de usar una opción de otro libro, confirma con el DM que está permitida en vuestra campaña.'),
  TutorialTopic(
      'class',
      'Clase y nivel',
      'La clase define tus capacidades de aventura; el nivel refleja tu progreso.',
      'Qué es una clase\nLa clase reúne las capacidades que tu aventurero ha aprendido. No equivale simplemente a su empleo anterior. Un guerrero destaca por su entrenamiento de combate; un pícaro por capacidades especializadas; un mago estudia magia. Los demás tipos de aventurero tienen sus propios rasgos y recursos.\n\nElige por lo que quieres hacer\nPiensa en acciones que te gustaría intentar: luchar en primera línea, apoyar a compañeros, investigar o utilizar magia. Consulta cómo funciona la clase antes de escoger. Cualquier personaje puede hablar y explorar; elegir una clase no limita todas sus decisiones a un único papel.\n\nNivel, rasgos y subclase\nEl nivel refleja el desarrollo del personaje. Los rasgos de clase son sus capacidades concretas y suelen indicar cuándo y cómo se usan. Una subclase es una especialización que se elige al nivel indicado por la clase; no se selecciona al mismo nivel en todas. Un personaje nuevo suele comenzar con pocas capacidades para aprenderlas gradualmente.\n\nQué es un recurso\nAlgunas capacidades se pueden usar libremente; otras gastan algo, como un espacio de conjuro o un uso de una capacidad. Lee cuándo se recupera ese recurso. Que una capacidad aparezca en la hoja no significa que puedas usarla sin límite.\n\nSubir de nivel\nEl DM y el grupo acuerdan el progreso de la campaña, mediante experiencia o hitos. Al subir debes revisar PG, rasgos nuevos, competencia y magia si corresponde. Algunas subidas incluyen mejoras de características y otras elecciones. No basta con cambiar el número de nivel sin actualizar la hoja.\n\nEn esta aplicación\nLa clase inicial aporta los datos que el formulario conoce. La gestión de progresión y de todas las elecciones de clase todavía es parcial. Revisa los cambios con el DM y guarda una hoja coherente; el tutorial explica el concepto y no implementa un asistente completo de subida de nivel.'),
  TutorialTopic(
      'alignment',
      'Alineamiento',
      'Describe tendencias morales y tu relación con las normas.',
      'Qué describe\nEl alineamiento es una orientación sobre cómo tu personaje tiende a tomar decisiones morales y relacionarse con las normas. Ayuda a imaginar su comportamiento, pero no reemplaza una personalidad ni obliga a elegir siempre la misma respuesta.\n\nLos dos ejes\nLegal, neutral o caótico describen su relación con el orden, los compromisos y la libertad personal. Bueno, neutral o malvado describen una tendencia moral respecto a los demás. Las combinaciones permiten matices: alguien puede valorar las leyes y preocuparse por el bienestar ajeno, o ayudar a otros incluso desobedeciendo una norma injusta.\n\nUn ejemplo sencillo\nUna aventurera ve que un guardia exige un pago injusto. Una orientación legal buena podría llevarla a denunciarlo ante una autoridad; una caótica buena podría llevarla a oponerse directamente. Son posibilidades para interpretar, no respuestas obligatorias ni bonificadores mecánicos.\n\nVerdadero Neutral\nIndica neutralidad en ambos ejes. No significa no tener opiniones o no sentir afecto. El personaje puede priorizar su comunidad, su supervivencia o un equilibrio personal sin seguir siempre un mismo extremo.\n\nPara una mesa que empieza\nDescribe una frase sobre lo que tu personaje valora y otra sobre lo que le cuesta aceptar. Acordad que todos puedan colaborar. «Mi personaje haría eso» no sustituye el consentimiento del grupo para perjudicar la experiencia de otros.\n\nEn esta aplicación\nEl campo guarda una etiqueta de interpretación en tu trasfondo. Elegirla no cambia automáticamente tus tiradas ni concede capacidades.'),
  TutorialTopic(
      'abilities',
      'Características y modificadores',
      'Fuerza, Destreza, Constitución, Inteligencia, Sabiduría y Carisma describen tus capacidades.',
      'Las seis características\nFuerza (FUE) representa esfuerzo físico, como empujar o levantar. Destreza (DES) representa agilidad y precisión. Constitución (CON) representa resistencia. Inteligencia (INT) representa razonamiento y conocimiento. Sabiduría (SAB) representa atención e intuición. Carisma (CAR) representa presencia e influencia, no solo belleza.\n\nPuntuación y modificador no son lo mismo\nLa puntuación es el valor de la característica. El modificador es el número, positivo o negativo, que se usa en muchas tiradas. Por ejemplo, una puntuación 14 da +2; 10 da +0; 8 da −1. No sumas 14 al d20: cuando corresponde esa característica, sumas su modificador +2.\n\nCómo se calcula\nEl modificador es (puntuación − 10) / 2, redondeado hacia abajo. No necesitas calcularlo mentalmente en cada turno: la hoja lo muestra. Dos puntuaciones consecutivas pueden tener el mismo modificador, como 14 y 15, que dan +2.\n\nCompra de puntos en esta app\nEl formulario usa un presupuesto de 27 puntos para valores base entre 8 y 15. «Base» significa antes de los bonificadores raciales. Elevar una característica cuesta parte del presupuesto, y los valores más altos cuestan más. Después se añaden los bonificadores raciales que tenga registrados el formulario. Las reglas también contemplan otros métodos, pero este asistente usa compra de puntos.\n\nElecciones de competencias\nLa clase no añade puntuaciones fijas a tus características. Elige el número de habilidades indicado entre las opciones de tu clase. Tu trasfondo concede otras dos competencias; si una se repite con la clase o la raza, elige una sustitución distinta. Ser competente suma tu bonificador de competencia (+2 en nivel 1) al modificador del atributo. El pícaro elige dos pericias en habilidades competentes, o una habilidad y herramientas de ladrón: una pericia duplica la competencia, no el modificador del atributo. Por ejemplo, DES 14 y competencia +2 dan Sigilo +4; con pericia dan +6. La hoja y el PDF muestran los totales de las 18 habilidades.\n\nCómo repartir sin saberlo todo\nLee qué características usa tu clase para sus capacidades y ataques. Decide en qué quieres destacar y acepta que otras puntuaciones serán más modestas. Pide al DM que revise el reparto antes de confirmar. No tienes que ser excelente en todo para ser útil al grupo.\n\nEjemplo de uso\nCon Destreza 14 tienes modificador +2. Si el DM pide una prueba simple de Destreza y tu d20 da 9, el total inicial es 11. Una habilidad en la que seas competente puede añadir otro bonificador; revisa su total en la hoja para no duplicarlo.\n\nEn esta aplicación\nLos botones + y − cambian el valor base. La fila muestra el valor final y su modificador. El bonificador de origen se identifica por separado. Estos valores no sustituyen la revisión de opciones raciales que el formulario aún simplifica.'),
  TutorialTopic(
      'background',
      'Trasfondo, historia y personalidad',
      'Explica quién eras antes de la aventura y qué te mueve ahora.',
      'Quién eras antes de aventurarte\nEl trasfondo explica tu vida anterior: dónde creciste, qué hacías y qué personas te importan. En las reglas, un trasfondo puede proporcionar competencias, idiomas, equipo y un rasgo. Es distinto de la clase: un aventurero entrenado como guerrero podría haber trabajado en un templo o en un barco.\n\nHistoria sin escribir una novela\nResponde tres preguntas: ¿de dónde vengo?, ¿por qué salgo de aventura?, ¿qué quiero conseguir ahora? Un párrafo basta para empezar. Puedes descubrir más de tu personaje mientras juegas. Acordar una conexión con otro aventurero ayuda a que el grupo tenga motivos para colaborar.\n\nIdeales, vínculos y defectos\nUn ideal es un principio que orienta tus decisiones: «nadie debería pasar hambre». Un vínculo es una persona, lugar u objetivo que te importa: «quiero recuperar el negocio de mi familia». Un defecto es una dificultad que puede complicarte la vida: «me cuesta confiar en autoridades». No tienen que ser excusas para perjudicar a otros jugadores.\n\nEjemplo listo para adaptar\n«Crecí reparando barcos. Salí a buscar a mi hermana después de recibir una carta extraña. Valoro cumplir mis promesas, conservo el mapa que ella me dio y suelo aceptar riesgos cuando creo que alguien necesita ayuda».\nEsta información ofrece al DM ideas para escenas y decisiones.\n\nEn esta aplicación\nHistoria, Ideales, Vínculos y Defectos guardan texto narrativo. Escribir «marinero» no concede automáticamente todas las competencias o el equipo de un trasfondo de reglas. Revisa esas elecciones con el DM y anótalas donde corresponda en la hoja.'),
  TutorialTopic(
      'avatar',
      'Nombre y apariencia',
      'Identifican a tu aventurero y ayudan a imaginarlo.',
      'Nombre y apariencia\nEl nombre identifica a tu aventurero en la hoja y en la campaña. Puede ser sencillo; elige uno que el grupo pueda recordar. Describe dos o tres detalles de apariencia, como ropa, postura o una cicatriz. No hace falta una imagen para poder jugar.\n\nJugador y personaje son distintos\nTu cuenta identifica a la persona que utiliza la aplicación. El nombre del personaje identifica al aventurero que interpretas. Puedes tener varios personajes en tu cuenta y elegir cuál participa en una campaña.\n\nQué es una URL de imagen\nEs una dirección que empieza normalmente por https:// y apunta a una imagen accesible. Un enlace a una página que contiene una foto no siempre es un enlace a la foto. Algunos sitios impiden que otras páginas muestren sus imágenes; por eso una dirección puede fallar aunque funcione al abrirla aparte.\n\nQué cambia en el juego\nEl nombre y la imagen no conceden bonificadores. Si un detalle de apariencia tiene un efecto mecánico, debe venir de una regla o de un acuerdo explícito con el DM. Puedes cambiar tu descripción para reflejar acontecimientos de la historia.'),
  TutorialTopic(
      'hp',
      'Puntos de golpe y dados de golpe',
      'Los PG reflejan cuánto daño puedes soportar; los dados de golpe ayudan a recuperarte.',
      'Actuales y máximos\nLos Puntos de golpe, abreviados PG, representan la capacidad de resistir daño. Los máximos son tu límite habitual; los actuales indican cuánto te queda. Tener 12 de 12 PG significa estar al máximo. Si recibes 5 de daño, quedas en 7 de 12. Una curación de 3 te dejaría en 10 de 12.\n\nNo son Clase de Armadura\nLa CA ayuda a determinar si un ataque te alcanza. Los PG se reducen cuando recibes daño. Puedes tener una CA alta y pocos PG, o al contrario. Son valores distintos y cumplen funciones distintas.\n\nQué ocurre al llegar a cero\nNormalmente caes inconsciente y comienzas a hacer salvaciones de muerte si no mueres de inmediato. El DM debe revisar también daño masivo y otros efectos. Una salvación de muerte usa un d20 sin el modificador habitual: 10 o más es éxito; menos de 10 es fallo. Tres éxitos estabilizan y tres fallos provocan la muerte. Un 1 cuenta como dos fallos y un 20 recupera 1 PG. Estar estable no significa recuperar de inmediato todos los PG ni poder actuar.\n\nDados de golpe\nSon un recurso de recuperación ligado a tu clase y nivel. Durante un descanso corto puedes gastar dados de golpe disponibles y sumar el modificador de Constitución a cada tirada para recuperar PG. No son el dado de ataque ni el bonificador de competencia.\n\nPG temporales de las reglas\nSon una reserva adicional proporcionada por algunos efectos. Se pierden antes que los PG normales, no se curan y no se suman entre sí: cuando recibes otra reserva eliges cuál conservar. No aumentan tus PG máximos.\n\nEn esta aplicación\nLos PG del rastreador de combate son números guardados solo durante esa pantalla. Que sean un registro temporal no significa que representen los PG temporales de las reglas. No se sincronizan con la hoja y el formulario muestra un cálculo inicial; confirma tus máximos y lleva el estado real del personaje con el DM.'),
  TutorialTopic(
      'ac',
      'Clase de Armadura (CA)',
      'Es el valor que un ataque debe alcanzar para impactarte.',
      'Qué significa CA\nClase de Armadura, o CA, es el número que una tirada de ataque debe normalmente igualar o superar para impactarte. No se resta al daño. Si un ataque no llega a la CA, normalmente falla y no se tira su daño por ese ataque.\n\nEjemplo paso a paso\nTu CA es 15. Un atacante saca 9 y tiene +4 al ataque: total 13, falla. Si saca 11 con ese mismo +4, el total es 15 y normalmente impacta. Después se determina el daño por separado. Los resultados naturales 1 y 20 en ataques tienen reglas especiales.\n\nDe dónde sale\nSin armadura, la base habitual es 10 más el modificador de Destreza. Las armaduras ligeras, medias y pesadas usan reglas diferentes; los escudos y ciertos rasgos también pueden intervenir. Algunas capacidades dan una forma alternativa de calcular la CA, no una suma que puedas acumular siempre con las demás.\n\nArmadura e inventario\nTener una armadura escrita en la mochila no significa llevarla puesta. Además, la competencia con esa armadura importa. Consulta sus requisitos y sus efectos con el DM antes de usarla.\n\nEn esta aplicación\nEl asistente calcula la CA sin armadura: normalmente 10 + modificador de DES. El bárbaro utiliza 10 + DES + CON y el monje 10 + DES + SAB. Estos son modificadores, no puntuaciones. El equipo inicial debe elegirse con el DM y después registrarse en la hoja. Escribir una armadura en el inventario todavía no recalcula su CA; aplica la fórmula de la armadura equipada y revisa escudos y condiciones de tus rasgos.'),
  TutorialTopic(
      'initiative',
      'Iniciativa y velocidad',
      'La iniciativa ordena los turnos; la velocidad limita tu movimiento.',
      'Iniciativa: quién actúa primero\nAl comenzar un combate haces una prueba de Destreza para iniciativa, junto con otros bonificadores si una capacidad los concede. El total determina tu lugar en el orden de turnos. Ejemplo: un 13 en el d20 y +2 de Destreza dan iniciativa 15. La iniciativa no es una tirada de ataque.\n\nVelocidad: cuánto te mueves\nLa velocidad es la distancia que puedes recorrer durante tu turno en condiciones normales. Se muestra en pies; ft es la abreviatura inglesa. Si tienes 30 pies, puedes repartirlos antes y después de tu acción. No tienes que gastar todo tu movimiento.\n\nTerreno y decisiones\nEl terreno difícil y ciertos efectos pueden reducir cuánto avanzas. Si usáis una cuadrícula, confirmad la distancia de cada casilla; una referencia habitual es 5 pies. Describe por dónde te mueves y el DM comprueba obstáculos, alcance y posibles ataques de oportunidad.\n\nEjemplo en la mesa\nUn personaje con iniciativa 15 actúa antes que otro con 11. En su turno mueve 10 pies, realiza una acción y luego decide si usa los 20 restantes. El orden se repite en la siguiente ronda salvo que las reglas o la situación indiquen un cambio.\n\nEn esta aplicación\nEl DM introduce los totales de iniciativa y pulsa Ordenar; también puede arrastrar los personajes. Reiniciar pone las iniciativas a cero y restaura los PG del rastreador. Estos valores se pierden al salir de la pantalla.'),
  TutorialTopic(
      'skills',
      'Habilidades, salvaciones y competencia',
      'Una competencia representa preparación: añade tu bonificador de competencia a las pruebas correspondientes. En nivel 1 es +2; no se suma dos veces.',
      'Características frente a habilidades\nUna característica es una capacidad amplia, como Destreza o Sabiduría. Una habilidad es un ámbito de aplicación, como Sigilo o Percepción. Para encontrar algo oculto, el DM podría pedir Sabiduría (Percepción). Para examinar cómo funciona un mecanismo, podría pedir Inteligencia (Investigación).\n\nQué significa competencia\nIndica entrenamiento en algo concreto. Cuando eres competente en la prueba correspondiente, añades el bonificador de competencia además del modificador de característica. No es obligatorio ser competente para intentar cualquier tarea: una regla o la situación pueden imponer requisitos concretos.\n\nEjemplo con números\nCon Destreza +2 y bonificador de competencia +2, un personaje competente en Sigilo tiene normalmente +4 en esa habilidad. Si el d20 da 8, su total es 12. Sin competencia tendría +2 y el mismo dado daría 10. Si la hoja muestra +4, no añadas otro +2 de competencia por segunda vez.\n\nTiradas de salvación\nResisten un peligro o efecto, en lugar de resolver una tarea que has elegido. El efecto indica qué característica usar y qué sucede con éxito o fallo. Por ejemplo, una trampa puede pedir una salvación de Destreza. Usas competencia solo si eres competente en esa salvación, no porque seas competente en alguna habilidad de Destreza.\n\nPericia y percepción pasiva\nPericia es un rasgo que puede duplicar el bonificador de competencia para usos concretos; no la tienes por marcar una habilidad. La percepción pasiva es un valor que el DM puede consultar sin pedir una tirada, basado en 10 más los bonificadores aplicables. No significa que tu personaje detecte automáticamente todo.\n\nEn esta aplicación\nEl contador 0/2 significa que has elegido cero de las dos competencias disponibles en ese grupo. Marca las habilidades que te interesan entre las opciones de tu clase. Las raciales y las del trasfondo se añaden también; si una se repite, el asistente pide otra habilidad como sustitución, sin sumar dos veces la competencia. El pícaro elige sus pericias después. Cada icono abre una explicación propia y Saber más lleva a su tema de la guía. Consultar ayuda no marca la casilla. La hoja y el PDF muestran el total de cada habilidad: úsalo con el d20 sin volver a sumar sus componentes.'),
  TutorialTopic(
      'equipment',
      'Equipo y ataques',
      'Tu inventario reúne lo que llevas; las armas indican cómo atacas.',
      'Qué contiene el inventario\nArmas para atacar, armaduras y escudos para protegerte, herramientas para tareas y suministros como cuerda, comida o antorchas. Un objeto sirve porque explica qué puedes intentar y porque algunas reglas describen sus efectos. Pregunta si un objeto está al alcance, equipado o guardado.\n\nAtaque y daño\nUn arma tiene un bonificador de ataque y una expresión de daño. El ataque usa un d20 para ver si impactas. El daño indica dados como 1d8 + 3 y se tira después de impactar. El bonificador de competencia puede formar parte del ataque, pero no se suma normalmente al daño del arma.\n\nEjemplo ilustrativo\nTu ataque tiene +5. Sacas 12: el total es 17. Contra CA 16 normalmente impactas. El daño es 1d8 + 3; el dado da 5, así que el daño inicial es 8. El DM aplica después resistencias, otros efectos o capacidades si corresponden.\n\nPropiedades y alcance\nAlgunas armas permiten utilizar Destreza en vez de Fuerza, tienen alcance especial o funcionan de otra manera al lanzarse. No deduzcas estas reglas solo por el nombre: lee las propiedades. La competencia con un arma y la competencia con una armadura son cosas distintas.\n\nMonedas y carga\npc, pp, pe, po y ppt representan cobre, plata, electro, oro y platino. Sirven para registrar riqueza e intercambios. Los objetos y monedas también pueden pesar. Acordad cómo llevar la carga con el DM y no confundáis un registro narrativo de mochila con un cálculo automático.\n\nEn esta aplicación\nEl inventario registra lo que llevas. Una lista de equipo inicial no sustituye elegir entre las opciones permitidas por tu clase. Escribir una armadura o arma no asegura que la app recalcule CA, ataques o peso. Revisa y actualiza la hoja con el DM.'),
  TutorialTopic(
      'spells',
      'Conjuros y trucos',
      'La magia tiene requisitos, tiempos y recursos propios.',
      'Qué es un conjuro\nEs una capacidad mágica con un texto que explica exactamente qué hace. No todos los personajes usan magia. Quien puede hacerlo debe consultar las reglas de su clase y la descripción del conjuro antes de lanzarlo.\n\nTrucos y espacios\nUn truco es un conjuro que normalmente puedes lanzar sin gastar espacios. Un espacio de conjuro es un recurso que gastas para lanzar determinados conjuros; no es el conjuro en sí. Puedes conocer varios conjuros y tener pocos espacios, de modo que debes decidir cuándo gastarlos.\n\nNivel de personaje y nivel de conjuro\nSon escalas distintas. Tener un personaje de nivel 3 no significa poder lanzar conjuros de nivel 3. La clase y su tabla de progresión determinan qué espacios y capacidades tienes. No lo deduzcas del número de nivel de tu hoja.\n\nConocer y preparar\nAlgunas clases conocen un conjunto de conjuros; otras preparan una selección según sus reglas. Un mago utiliza además un libro de conjuros. Tener un conjuro escrito en la lista no garantiza que esté preparado ni que puedas lanzarlo ahora.\n\nQué revisar antes de lanzar\nLee el tiempo de lanzamiento, alcance, objetivos, componentes, duración y efecto. Los componentes pueden ser palabras (verbales), gestos (somáticos) u objetos (materiales). Algunos materiales tienen costes o se consumen; consulta el texto. Comprueba también el espacio y los demás recursos que necesitas.\n\nAtaques y salvaciones\nAlgunos conjuros te piden una tirada de ataque. Otros hacen que el objetivo tire una salvación contra tu CD de conjuro. No tires un ataque cuando el texto pide una salvación al objetivo. Otros efectos no requieren ninguno de esos pasos.\n\nConcentración\nSi un conjuro requiere concentración, mantenerlo limita otros conjuros de concentración. No puedes concentrarte en dos a la vez. Recibir daño puede exigir una salvación de Constitución para mantenerla. Lee cuándo termina el efecto.\n\nEn esta aplicación\nLa pestaña organiza tu información de magia. La app no comprueba automáticamente todos los requisitos de preparación, espacios o concentración. Usa la hoja y el texto del conjuro con el DM antes de declarar el lanzamiento.'),
  TutorialTopic(
      'rests',
      'Descansos',
      'Los descansos permiten recuperar recursos según las reglas de tu clase.',
      'Por qué descansar\nTu personaje puede gastar PG, dados de golpe y usos de capacidades durante la aventura. Un descanso permite recuperar determinados recursos. Es tiempo que transcurre dentro de la historia, no solo una pausa para que los jugadores coman.\n\nDescanso corto\nNormalmente dura al menos una hora de actividad ligera. Puedes gastar uno o más dados de golpe disponibles para recuperar PG: tira el dado correspondiente y suma el modificador de Constitución. Puedes decidir si gastas otro después de ver el resultado. No gastes dados que ya no te queden.\n\nEjemplo de recuperación\nTienes 5 de 12 PG, un dado de golpe d10 disponible y Constitución +2. Gastas ese dado y sacas 4: recuperas 6 PG y quedas en 11 de 12. El dado gastado deja de estar disponible hasta que lo recuperes según las reglas.\n\nDescanso largo\nNormalmente requiere al menos ocho horas y las condiciones de descanso de las reglas. Recuperas los PG perdidos y dados de golpe gastados hasta la mitad de tu total, redondeada hacia abajo, con mínimo uno. No puedes beneficiarte de más de un descanso largo en un periodo de 24 horas, y debes tener al menos 1 PG al comenzarlo. Interrupciones y algunos rasgos pueden cambiar cómo se resuelve.\n\nOtros recursos\nLee tu clase: ciertos recursos vuelven en un descanso corto y otros en uno largo. No supongas que todos se recuperan juntos. Antes de marcar un recurso como disponible, confirma qué descanso lo restaura.\n\nEn la mesa y en esta app\nEl DM comprueba si el lugar y la situación permiten descansar. Declara dónde descansas y cómo se organiza el grupo. Actualiza tu registro de PG y recursos cuando corresponda; la aplicación no ejecuta automáticamente todo el proceso.'),
  TutorialTopic(
      'invitation',
      'Campañas y código de invitación',
      'El código permite incorporar a un jugador con un personaje libre.',
      'Qué es una campaña en la app\nEs el espacio que reúne al DM y a los personajes de los jugadores. Guarda nombre, descripción y notas de preparación, y permite consultar al grupo. La aventura se juega hablando y resolviendo acciones; crear este espacio no inicia una partida automática.\n\nSi eres DM\nAbre Campañas y pulsa Crear campaña. Escribe un nombre y una descripción, confirma y copia el código de invitación. Compártelo con tu grupo. También puedes recuperarlo desde Dungeon Master al desplegar la campaña. Después abre la mesa para consultar a los aventureros que se unan.\n\nSi eres jugador\nCrea primero un personaje o comprueba que tienes uno libre en Mis Personajes. Pide al DM el código. En Campañas pulsa Unirse, introduce el código, elige el Personaje a usar y confirma. Después entra desde la tarjeta de la campaña.\n\nRestricciones de LA CRIPTA\nUn personaje solo puede pertenecer a una campaña activa. Para usar otro, crea uno nuevo o termina la campaña actual de ese personaje en Mis Personajes. El DM de una campaña no puede unirse a ella como jugador. Estas son decisiones de organización de la aplicación, no reglas generales de D&D.\n\nSi algo no aparece\nVerifica que utilizas tu cuenta, que el personaje está libre y que el código corresponde a esa campaña. Pide al DM que lo copie de nuevo. Usa actualizar para consultar cambios del grupo; no asumas que todos los datos se muestran en tiempo real.'),
  TutorialTopic(
      'campaign-name',
      'Nombre de la campaña',
      'Es el título con el que tu grupo reconocerá esta aventura.',
      'El título de tu mesa\nEs la etiqueta que identifica esta aventura en la lista de Campañas y al abrirla. Elige algo que tu grupo pueda recordar y distinguir de otras mesas. El nombre es obligatorio al crear la campaña.\n\nUn nombre no tiene que contar toda la historia\n«Las ruinas de la frontera» o «El faro perdido» pueden ser suficientes. Evita revelar en el título una sorpresa que los jugadores aún no conocen. El contexto inicial va en Descripción y los secretos del DM en Notas Ocultas.\n\nNombre, código y personaje\nEl nombre identifica la aventura; el código permite incorporarse a su espacio; el personaje es el aventurero con el que participa un jugador. Son tres elementos distintos. Escribir un nombre no permite unirse si no tienes el código correcto.\n\nQué sucede al crear\nAl confirmar Crear, la aplicación registra la campaña, te convierte en su Dungeon Master y genera el código. Después puedes compartirlo con los jugadores para que se unan con personajes disponibles.'),
  TutorialTopic(
      'campaign-description',
      'Descripción de la campaña',
      'Presenta la aventura a los jugadores sin revelar secretos del DM.',
      'Lo que sabe el grupo al empezar\nLa descripción presenta la propuesta de aventura: dónde comienza, qué problema conocen los protagonistas y qué tono esperáis. Es texto público para los jugadores de la campaña. No necesitas resumir toda la historia ni decidir cómo acabará.\n\nUna plantilla práctica\nEscribe un lugar, un problema y un motivo para actuar. Ejemplo: «En una villa junto al bosque desaparecen los suministros. La alcaldesa pide ayuda para seguir unas huellas hasta unas ruinas. El grupo llegará como viajeros dispuestos a investigar». Esto permite comenzar a conversar y tomar decisiones.\n\nTono y expectativas\nPuedes indicar si la mesa busca misterio, exploración o aventura heroica y si admite personajes principiantes. Los acuerdos detallados sobre límites y horarios conviene conversarlos con el grupo antes de jugar.\n\nQué no deberías revelar aquí\nNo escribas quién es el culpable, dónde está una pista secreta o cómo se desactiva una trampa si los personajes aún no lo saben. Usa Notas Ocultas para esa información.\n\nEn esta aplicación\nEscribe la descripción al crear la campaña. Los jugadores pueden consultarla en su vista de la mesa. La aplicación no transforma este texto en misiones automáticas: sirve de contexto para el grupo.'),
  TutorialTopic(
      'join-character',
      'Personaje para la campaña',
      'Elige el aventurero con el que participarás como jugador.',
      'Cuenta y aventurero\nTu cuenta puede guardar varios personajes. Al unirte eliges cuál de ellos vivirá esa campaña. Piensa en él como tu protagonista, con una hoja que debes revisar y mantener al día.\n\nPor qué el selector puede estar vacío\nLa aplicación solo ofrece personajes disponibles. Si todos están vinculados a campañas activas, no aparecen como libres. Puedes crear otro o terminar la campaña actual de un personaje desde Mis Personajes si eso corresponde a lo acordado con tu grupo.\n\nAntes de confirmar\nComprueba el nombre del aventurero, revisa su hoja y asegúrate de que encaja con el nivel y las opciones que acordó el DM. La aplicación permite elegirlo, pero no sustituye ese acuerdo.\n\nCómo completar la unión\nIntroduce el código de la campaña, elige el personaje y pulsa Unirse. El código identifica la mesa; el selector identifica al aventurero que aportas. Si tú diriges esa campaña, entra como DM desde Dungeon Master en vez de intentar unirte como jugador.'),
  TutorialTopic(
      'status',
      'Estados narrativos y condiciones',
      'Los estados de la app cuentan lo que ocurre en la historia.',
      'Dos conceptos distintos\nUna condición de juego describe un efecto con reglas concretas, como envenenado, derribado o inconsciente. Un estado narrativo de la app resume un acontecimiento de la historia, como vivo, perdido o resucitado. No son intercambiables.\n\nCómo usar una condición\nLee qué efecto la provoca, qué modifica y cuándo termina. Por ejemplo, decir que un personaje está inconsciente afecta a sus posibilidades de actuar según las reglas. No basta con inventar una penalización genérica para todas las condiciones.\n\nCómo usar un estado narrativo\nEl DM puede marcar que un aventurero está perdido porque no se conoce su paradero, aunque no esté afectado por una condición mecánica. Una nota breve puede explicar «desapareció al cruzar el portal». Esto ayuda a recordar la historia compartida.\n\nLlegar a cero PG\nNo cambies automáticamente la etiqueta a muerto por ver 0 PG. Hay que resolver inconsciencia, salvaciones de muerte y otras reglas que correspondan. El DM confirma el resultado antes de registrar un estado narrativo definitivo.\n\nEn esta aplicación\nEl DM cambia las etiquetas desde Estado de Personajes y puede añadir una nota. Los jugadores consultan el resultado. Estas etiquetas no ajustan automáticamente ataques, salvaciones, raza ni PG: sus consecuencias deben resolverse y reflejarse en la hoja cuando proceda.'),
  TutorialTopic(
      'notes',
      'Notas privadas del DM',
      'Guarda apuntes de la campaña que los jugadores no pueden ver.',
      'Para qué sirven\nLas notas privadas reúnen información que el DM necesita preparar o recordar sin revelarla todavía al grupo. Pueden incluir motivos de un habitante, pistas escondidas, consecuencias de acciones o ideas para la siguiente sesión.\n\nUna estructura sencilla\nOrganiza cada sesión con cuatro apartados: situación inicial, personas importantes, pistas disponibles y posibles consecuencias. Anota también lo que el grupo cambió durante la partida. Puedes preparar posibilidades sin decidir por adelantado todo lo que harán los jugadores.\n\nEjemplo de nota privada\n«La guardia reconoce el símbolo del mapa, pero teme hablar. Si le muestran que buscan ayudar, cuenta dónde vio al explorador. Si hacen mucho ruido, los habitantes de las ruinas se pondrán en alerta».\nEsto ofrece respuestas a las decisiones del grupo sin obligarlo a seguir un único camino.\n\nQué va en la descripción pública\nEl escenario y el problema inicial pertenecen a la descripción de campaña. La identidad del responsable o una solución secreta pertenecen a estas notas. No pongas secretos en el texto que los jugadores pueden consultar.\n\nEn esta aplicación\nEscribe en Notas Ocultas y pulsa Guardar notas antes de salir o actualizar. Solo el DM de la campaña recibe esas notas. El botón de actualizar vuelve a cargar la información guardada y puede reemplazar lo que aún no has guardado.'),
  TutorialTopic(
      'strength',
      'Fuerza (FUE)',
      'Mide el esfuerzo físico: levantar, empujar, trepar o golpear con muchas armas cuerpo a cuerpo. No determina cuánto daño puedes resistir.',
      'Qué representa\nFuerza describe la potencia física y la capacidad de realizar esfuerzos. Un personaje fuerte puede empujar una puerta pesada, sujetar una cuerda contra una corriente o mover una carga. El DM decide si el intento necesita una tirada y qué condiciones tiene.\n\nAtletismo y tareas físicas\nAtletismo es la habilidad asociada normalmente a Fuerza. Puede intervenir al trepar, nadar en condiciones difíciles o realizar ciertos saltos. No toda actividad física es Acrobacias: mantener el equilibrio y levantar una reja no requieren necesariamente la misma característica. Explica tu método y deja que el DM determine la prueba.\n\nEjemplo de tirada\nQuieres apartar una viga para liberar un paso. El DM pide Fuerza. Si tienes Fuerza 14, su modificador es +2. Un 11 en el d20 da un total de 13. Si la prueba permite utilizar Atletismo y eres competente, añade el bonificador correspondiente una sola vez. No sumes la puntuación 14 al dado.\n\nArmas y carga\nMuchas armas cuerpo a cuerpo utilizan Fuerza para sus tiradas de ataque y daño. Hay excepciones según las propiedades del arma o los rasgos del personaje; no elijas el bonificador únicamente por su aspecto. La capacidad de carga habitual depende de tu puntuación de Fuerza, mientras que la aplicación no calcula automáticamente todos los pesos.\n\nCómo repartir puntos\nConsidera Fuerza si imaginas un aventurero que utiliza esfuerzo físico o armas que dependan de ella. Guerrero, bárbaro o paladín pueden tener motivos para valorarla, pero importa el estilo concreto del personaje. Una Fuerza modesta no impide participar en la historia: puedes emplear herramientas, colaborar o buscar otro método.\n\nEn esta aplicación\nLa fila FUE muestra la puntuación final y, debajo, el modificador. El texto racial indica el bonificador de origen registrado. Los botones cambian la puntuación base dentro del presupuesto. La ayuda de esta fila abre únicamente el tema de Fuerza.'),
  TutorialTopic(
      'dexterity',
      'Destreza (DES)',
      'Mide agilidad y precisión. Interviene en Sigilo, Acrobacias, Juego de manos, iniciativa y muchos ataques a distancia; su efecto sobre la armadura depende del equipo.',
      'Qué representa\nDestreza describe coordinación, equilibrio, movimientos precisos y rapidez de respuesta. Puede ayudarte a caminar sobre una superficie estrecha, moverte sin ruido o manipular algo delicadamente. No equivale a fuerza muscular ni garantiza una velocidad de movimiento mayor.\n\nTres habilidades habituales\nAcrobacias se relaciona con equilibrio y maniobras de agilidad. Juego de manos se relaciona con movimientos discretos y precisos de las manos. Sigilo se utiliza al intentar pasar inadvertido. El DM considera si hay dónde ocultarte, quién puede percibirte y qué estás intentando hacer.\n\nEjemplo de Sigilo\nQuieres cruzar un patio sin alertar a un guardia. Con Destreza 14 tienes modificador +2. Si eres competente en Sigilo y tu competencia es +2, el bonificador habitual de la habilidad es +4. Sacar 9 en el d20 da 13. Si tu hoja ya muestra Sigilo +4, no añadas otros +2 de Destreza.\n\nIniciativa, armas y armadura\nLa iniciativa utiliza normalmente el modificador de Destreza para establecer el orden de turnos. Las armas a distancia suelen utilizarlo; algunas armas permiten elegirlo por sus propiedades. También interviene en ciertas formas de calcular CA: armaduras ligeras, medias y pesadas aplican reglas diferentes. No añadas Destreza completa a cualquier armadura.\n\nCómo repartir puntos\nPuede ser importante para un aventurero que se mueva con discreción, use armas dependientes de Destreza o quiera responder con rapidez. Consulta qué capacidades de tu clase la utilizan. Una puntuación alta no permite atravesar cualquier obstáculo sin tirar ni sustituye las decisiones del personaje.\n\nEn esta aplicación\nDES muestra tu puntuación final y su modificador. La guía explica sus usos, pero el formulario inicial no calcula todas las combinaciones de equipo y CA. Confirma la armadura y las propiedades de las armas con el DM.'),
  TutorialTopic(
      'constitution',
      'Constitución (CON)',
      'Mide resistencia física. Afecta a los Puntos de golpe y a las tiradas para resistir ciertos peligros o mantener concentración; no tiene una habilidad propia.',
      'Qué representa\nConstitución describe cuánto esfuerzo y qué condiciones físicas puede soportar tu personaje. Puede importar ante venenos, enfermedades o esfuerzos prolongados cuando una regla o el DM pida una prueba o salvación. No significa que seas inmune a esos peligros.\n\nCómo influye en los PG\nEl modificador de Constitución forma parte del cálculo de Puntos de golpe. Por ejemplo, un guerrero de nivel 1 con dado de golpe d10 y Constitución 14 tiene normalmente 10 + 2 = 12 PG máximos. La puntuación 14 no se suma directamente: se usa el modificador +2.\n\nDados de golpe y recuperación\nEn un descanso corto, los dados de golpe disponibles permiten recuperar PG según las reglas. El modificador de Constitución interviene en esa recuperación. Los dados de golpe son un recurso distinto de los PG actuales: tener una Constitución alta no significa curarte por completo después de cada combate.\n\nSalvaciones y concentración\nUna salvación de Constitución permite resistir efectos que indiquen esa característica. Si mantienes un conjuro de concentración y recibes daño, normalmente debes hacer la salvación de Constitución que exigen sus reglas para conservarlo. Añade competencia solo si eres competente en esa salvación. No sumes el bonificador de lanzamiento de conjuros en su lugar.\n\nNo hay una habilidad de Constitución\nLas habilidades de la hoja, como Atletismo o Percepción, no incluyen una habilidad estándar asociada a Constitución. Eso no impide que el DM pueda pedir una prueba directa de esta característica cuando corresponda.\n\nCómo repartir puntos y leer la app\nPuede ayudar a cualquier aventurero que necesite resistir daño o mantener concentración. CON muestra el valor final y su modificador, y el resumen muestra los PG iniciales calculados. Si el modificador cambia al progresar, los PG máximos deben revisarse con efecto retroactivo según las reglas; la app no gestiona automáticamente todas esas revisiones.'),
  TutorialTopic(
      'intelligence',
      'Inteligencia (INT)',
      'Mide razonamiento y conocimientos. Se utiliza en Investigación, Arcanos, Historia, Naturaleza y Religión, y es la característica de lanzamiento del mago.',
      'Qué representa\nInteligencia describe memoria, razonamiento y conocimientos del personaje. Ayuda a relacionar pistas, recordar información aprendida o entender un mecanismo. No mide la inteligencia de la persona que juega: puedes pedir al DM qué sabe tu aventurero aunque tú desconozcas el tema.\n\nLas habilidades asociadas\nArcanos trata conocimientos sobre magia; Historia, acontecimientos y culturas del pasado; Naturaleza, conocimientos del entorno natural; Religión, tradiciones y temas religiosos. Investigación se utiliza para examinar indicios y deducir información. El DM determina cuál es relevante para la tarea concreta.\n\nInteligencia frente a Sabiduría\nPercibir una marca poco visible puede depender de Sabiduría (Percepción). Estudiar esa marca y deducir qué pieza activa un mecanismo puede depender de Inteligencia (Investigación). No son dos nombres para una misma prueba: importa si intentas percibir algo o razonar a partir de la información.\n\nEjemplo de Investigación\nEncuentras un cofre con un cierre extraño. Explicas que examinas las piezas sin tocarlas. El DM pide Investigación. Con Inteligencia 16 el modificador es +3; si además eres competente y tu competencia es +2, el bonificador habitual es +5. Un 8 en el d20 da un total de 13.\n\nRelación con el mago\nEl mago utiliza Inteligencia como característica de lanzamiento. Su modificador participa en sus ataques de conjuro y en la CD que deben superar los objetivos cuando un conjuro exige una salvación. La CD es un objetivo numérico, no una tirada adicional del mago. Otras clases pueden utilizar características distintas para su magia.\n\nCómo repartir puntos y leer la app\nValora Inteligencia si tus capacidades dependen de ella o quieres destacar al razonar y recordar conocimientos. La fila INT cambia la puntuación base; la hoja muestra el modificador final. Escribir una idea inteligente durante la partida sigue siendo válido aunque tu puntuación no sea alta: el DM decide qué requiere una tirada.'),
  TutorialTopic(
      'wisdom',
      'Sabiduría (SAB)',
      'Mide atención e intuición. Ayuda a percibir el entorno y valorar situaciones mediante Percepción, Perspicacia, Medicina, Supervivencia y Trato con animales.',
      'Qué representa\nSabiduría describe atención a lo que sucede, intuición y experiencia práctica. Puede ayudarte a notar un ruido, interpretar una actitud o reconocer señales del entorno. No significa saber todas las respuestas ni poder leer pensamientos.\n\nLas habilidades asociadas\nPercepción permite advertir información mediante los sentidos. Perspicacia ayuda a valorar intenciones o actitudes; no obliga a otro personaje a revelar toda la verdad. Medicina, Supervivencia y Trato con animales resuelven tareas de sus ámbitos cuando corresponda. Describe tu acción y el DM identifica la habilidad pertinente.\n\nEjemplo de Percepción\nAl entrar en unas ruinas dices que escuchas antes de avanzar. El DM pide Percepción. Con Sabiduría 12 tienes modificador +1. Si eres competente y tu competencia es +2, el total habitual de la habilidad es +3. Un 10 en el d20 da un resultado de 13.\n\nQué es la percepción pasiva\nEs un valor que el DM puede consultar sin pedir una tirada. Con los bonificadores del ejemplo, el valor habitual es 10 + 1 + 2 = 13, antes de otros efectos. No significa detectar siempre cualquier trampa: intervienen la dificultad, las circunstancias y las reglas. Tampoco es un segundo dado que tires después de fallar.\n\nSabiduría frente a Inteligencia\nNotar una irregularidad suele relacionarse con percepción; analizar su funcionamiento puede relacionarse con investigación. Si quieres hacer ambas cosas, explica tus pasos. No elijas una característica distinta únicamente porque su número sea más alto.\n\nMagia y reparto de puntos\nClérigos, druidas y exploradores utilizan Sabiduría para su lanzamiento de conjuros según sus reglas de clase. Otros personajes también pueden beneficiarse de atención e intuición. La fila SAB muestra puntuación y modificador; comprueba competencias y bonificadores de Percepción en la hoja sin sumarlos dos veces.'),
  TutorialTopic(
      'charisma',
      'Carisma (CAR)',
      'Mide presencia e influencia, no solo belleza. Se usa en Persuasión, Engaño, Intimidación e Interpretación, y varias clases lo utilizan para lanzar conjuros.',
      'Qué representa\nCarisma describe presencia, confianza y capacidad de influir o expresarse. No equivale a belleza física, simpatía constante o volumen de voz. Un aventurero reservado puede tener una presencia poderosa; otro muy hablador puede no persuadir con facilidad.\n\nLas habilidades asociadas\nPersuasión se relaciona con convencer de forma apropiada a la situación. Engaño interviene al intentar ocultar o falsear información. Intimidación implica presión o amenazas. Interpretación se relaciona con actuaciones. El método y las circunstancias importan: no basta con decir «uso Carisma» para conseguir cualquier resultado.\n\nEjemplo de Persuasión\nQuieres convencer a una comerciante de que os permita pasar la noche en su almacén. Ofreces proteger la mercancía y explicas por qué necesitas ayuda. El DM puede pedir Persuasión. Con Carisma 14 (+2) y competencia +2, un 11 en el d20 da un total habitual de 15.\n\nQué no consigue una tirada\nPersuadir no es controlar la mente. Un resultado alto no obliga a aceptar algo imposible o contrario a todo lo que ese personaje valora. El DM determina qué puede conseguir tu propuesta. Del mismo modo, no tienes que pronunciar un discurso perfecto: describe la intención de tu aventurero.\n\nCarisma y magia\nBardos, hechiceros, brujos y paladines utilizan Carisma como característica de lanzamiento según las reglas de su clase. Su modificador participa en los bonificadores de magia pertinentes; no sustituye el texto del conjuro ni proporciona espacios adicionales por sí solo.\n\nCómo repartir puntos y leer la app\nPuede ser útil si tus capacidades usan Carisma o te interesa influir en conversaciones. La fila CAR muestra puntuación y modificador. Revisa también las competencias de las habilidades sociales. Una puntuación baja no te prohíbe hablar: puedes participar y proponer ideas igualmente.'),
  TutorialTopic(
      'skill-acrobacias',
      'Acrobacias',
      'Equilibrio y coordinación corporal para maniobras de agilidad. Característica habitual: DES.',
      'Qué representa\nTe ayuda a controlar el cuerpo cuando importa mantener el equilibrio o realizar una maniobra precisa. Su característica habitual es DES. La habilidad describe una tarea; tener competencia indica preparación en esa tarea.\n\nUna escena de ejemplo\nUna pasarela de un molino se inclina mientras avanzas. Dices que flexionas las rodillas y buscas mantenerte en el centro. El DM puede pedir Acrobacias si hay incertidumbre. Primero describe lo que quieres conseguir y cómo lo intentas; el DM decide si necesitas dados.\n\nCómo leer el bonificador\nCon DES 14 tienes modificador +2. En nivel 1, si eres competente en Acrobacias, añades competencia +2: el total de la habilidad es +4. Un 11 en el d20 da 15. Si no eres competente, normalmente usas +2 y ese mismo dado da 13. Si una capacidad te concede pericia aplicable, el bonificador sería +6. No sumes otra vez lo que ya incluye la hoja.\n\nLímites y diferencias\nNo reemplaza automáticamente Atletismo para trepar, nadar o saltar. Una voltereta no concede movimiento adicional ni evita un ataque por sí sola.\n\nCómo elegir y usar la ayuda\nUn aventurero que imagines ágil puede aprovecharla, independientemente de su clase. En el formulario, marcar Acrobacias gasta una de las elecciones disponibles del grupo. Las competencias concedidas por raza o trasfondo se registran aparte. El icono de ayuda explica la habilidad sin marcarla; Saber más abre este tema y Volver conserva tu selección.'),
  TutorialTopic(
      'skill-trato_animales',
      'Trato con animales',
      'Comprender y manejar las reacciones de animales. Característica habitual: SAB.',
      'Qué representa\nSe relaciona con reconocer el comportamiento de un animal y actuar de forma adecuada al acercarte o manejarlo. Su característica habitual es SAB. La habilidad describe una tarea; tener competencia indica preparación en esa tarea.\n\nUna escena de ejemplo\nUna mula se detiene ante un sendero ruidoso. Explicas que le das espacio, bajas la voz y pruebas a tranquilizarla antes de continuar. El DM puede pedir Trato con animales. Primero describe lo que quieres conseguir y cómo lo intentas; el DM decide si necesitas dados.\n\nCómo leer el bonificador\nCon SAB 14 tienes modificador +2. En nivel 1, si eres competente en Trato con animales, añades competencia +2: el total de la habilidad es +4. Un 11 en el d20 da 15. Si no eres competente, normalmente usas +2 y ese mismo dado da 13. Si una capacidad te concede pericia aplicable, el bonificador sería +6. No sumes otra vez lo que ya incluye la hoja.\n\nLímites y diferencias\nNo es comunicación mágica ni dominio de cualquier criatura. Un animal tiene necesidades y límites; no obedece una orden imposible por una tirada alta.\n\nCómo elegir y usar la ayuda\nPuede ser útil si tu historia incluye cuidado de animales o viajes con monturas. En el formulario, marcar Trato con animales gasta una de las elecciones disponibles del grupo. Las competencias concedidas por raza o trasfondo se registran aparte. El icono de ayuda explica la habilidad sin marcarla; Saber más abre este tema y Volver conserva tu selección.'),
  TutorialTopic(
      'skill-arcanos',
      'Arcanos',
      'Conocimientos sobre magia y fenómenos sobrenaturales. Característica habitual: INT.',
      'Qué representa\nRefleja lo que tu personaje ha aprendido acerca de la magia, sus tradiciones y fenómenos relacionados. Su característica habitual es INT. La habilidad describe una tarea; tener competencia indica preparación en esa tarea.\n\nUna escena de ejemplo\nEncuentras dibujos extraños en una puerta y preguntas si recuerdas haber visto símbolos semejantes en tus estudios. El DM puede pedir Arcanos para determinar qué información conoces. Primero describe lo que quieres conseguir y cómo lo intentas; el DM decide si necesitas dados.\n\nCómo leer el bonificador\nCon INT 14 tienes modificador +2. En nivel 1, si eres competente en Arcanos, añades competencia +2: el total de la habilidad es +4. Un 11 en el d20 da 15. Si no eres competente, normalmente usas +2 y ese mismo dado da 13. Si una capacidad te concede pericia aplicable, el bonificador sería +6. No sumes otra vez lo que ya incluye la hoja.\n\nLímites y diferencias\nSaber sobre magia no permite lanzar conjuros, detectar toda magia ni identificar automáticamente un objeto. Lee las capacidades concretas que conceden esos efectos.\n\nCómo elegir y usar la ayuda\nPuede encajar con un personaje estudioso de lo sobrenatural; no exige que sea mago. En el formulario, marcar Arcanos gasta una de las elecciones disponibles del grupo. Las competencias concedidas por raza o trasfondo se registran aparte. El icono de ayuda explica la habilidad sin marcarla; Saber más abre este tema y Volver conserva tu selección.'),
  TutorialTopic(
      'skill-atletismo',
      'Atletismo',
      'Esfuerzo físico en retos de trepar, nadar o saltar. Característica habitual: FUE.',
      'Qué representa\nSe utiliza cuando el reto requiere potencia física y esfuerzo, con las condiciones que establezca el DM. Su característica habitual es FUE. La habilidad describe una tarea; tener competencia indica preparación en esa tarea.\n\nUna escena de ejemplo\nUna cuerda cuelga de un balcón mojado. Explicas cómo te sujetas y trepas; el DM puede pedir Atletismo para resolver la dificultad. Primero describe lo que quieres conseguir y cómo lo intentas; el DM decide si necesitas dados.\n\nCómo leer el bonificador\nCon FUE 14 tienes modificador +2. En nivel 1, si eres competente en Atletismo, añades competencia +2: el total de la habilidad es +4. Un 11 en el d20 da 15. Si no eres competente, normalmente usas +2 y ese mismo dado da 13. Si una capacidad te concede pericia aplicable, el bonificador sería +6. No sumes otra vez lo que ya incluye la hoja.\n\nLímites y diferencias\nNo todo movimiento necesita una tirada. Las distancias de salto y las reglas de movimiento siguen aplicándose; competencia no significa fuerza ilimitada.\n\nCómo elegir y usar la ayuda\nPuede ayudarte si te interesa superar obstáculos físicos o participar en situaciones que exigen fuerza. En el formulario, marcar Atletismo gasta una de las elecciones disponibles del grupo. Las competencias concedidas por raza o trasfondo se registran aparte. El icono de ayuda explica la habilidad sin marcarla; Saber más abre este tema y Volver conserva tu selección.'),
  TutorialTopic(
      'skill-engano',
      'Engaño',
      'Ocultar o falsear información de manera convincente. Característica habitual: CAR.',
      'Qué representa\nRepresenta la capacidad de mantener una versión falsa o disimular intenciones cuando intentas que alguien la crea. Su característica habitual es CAR. La habilidad describe una tarea; tener competencia indica preparación en esa tarea.\n\nUna escena de ejemplo\nUna vigilante pregunta por qué llevas un paquete al almacén. Inventas que el encargado lo espera y describes cómo sostienes tu versión. El DM puede pedir Engaño. Primero describe lo que quieres conseguir y cómo lo intentas; el DM decide si necesitas dados.\n\nCómo leer el bonificador\nCon CAR 14 tienes modificador +2. En nivel 1, si eres competente en Engaño, añades competencia +2: el total de la habilidad es +4. Un 11 en el d20 da 15. Si no eres competente, normalmente usas +2 y ese mismo dado da 13. Si una capacidad te concede pericia aplicable, el bonificador sería +6. No sumes otra vez lo que ya incluye la hoja.\n\nLímites y diferencias\nNo controla pensamientos ni elimina pruebas evidentes. Di qué versión presentas y considera qué sabe la otra persona. No sirve como permiso para perjudicar a otros jugadores.\n\nCómo elegir y usar la ayuda\nPuede encajar con un personaje que utiliza identidades, secretos o distracciones en situaciones sociales. En el formulario, marcar Engaño gasta una de las elecciones disponibles del grupo. Las competencias concedidas por raza o trasfondo se registran aparte. El icono de ayuda explica la habilidad sin marcarla; Saber más abre este tema y Volver conserva tu selección.'),
  TutorialTopic(
      'skill-historia',
      'Historia',
      'Recordar información sobre acontecimientos y sociedades del pasado. Característica habitual: INT.',
      'Qué representa\nRefleja recuerdos y conocimientos que tu personaje puede relacionar con hechos históricos. Su característica habitual es INT. La habilidad describe una tarea; tener competencia indica preparación en esa tarea.\n\nUna escena de ejemplo\nVes un estandarte deteriorado en una fortaleza abandonada y preguntas qué recuerdas de la familia que lo utilizaba. El DM puede pedir Historia para precisar lo que sabes. Primero describe lo que quieres conseguir y cómo lo intentas; el DM decide si necesitas dados.\n\nCómo leer el bonificador\nCon INT 14 tienes modificador +2. En nivel 1, si eres competente en Historia, añades competencia +2: el total de la habilidad es +4. Un 11 en el d20 da 15. Si no eres competente, normalmente usas +2 y ese mismo dado da 13. Si una capacidad te concede pericia aplicable, el bonificador sería +6. No sumes otra vez lo que ya incluye la hoja.\n\nLímites y diferencias\nNo revela cualquier secreto antiguo ni sustituye buscar pruebas. El DM puede decir que esa información todavía es desconocida para tu personaje.\n\nCómo elegir y usar la ayuda\nPuede servir a un estudioso, un cronista o alguien interesado en entender el pasado de la campaña. En el formulario, marcar Historia gasta una de las elecciones disponibles del grupo. Las competencias concedidas por raza o trasfondo se registran aparte. El icono de ayuda explica la habilidad sin marcarla; Saber más abre este tema y Volver conserva tu selección.'),
  TutorialTopic(
      'skill-perspicacia',
      'Perspicacia',
      'Valorar actitudes e intenciones a partir de señales observables. Característica habitual: SAB.',
      'Qué representa\nSe relaciona con interpretar comportamiento, tono y otras pistas para valorar una situación social. Su característica habitual es SAB. La habilidad describe una tarea; tener competencia indica preparación en esa tarea.\n\nUna escena de ejemplo\nUna guía insiste en marcharse justo cuando preguntas por un camino. Describes que observas su nerviosismo y preguntas si parece temer algo. El DM puede pedir Perspicacia. Primero describe lo que quieres conseguir y cómo lo intentas; el DM decide si necesitas dados.\n\nCómo leer el bonificador\nCon SAB 14 tienes modificador +2. En nivel 1, si eres competente en Perspicacia, añades competencia +2: el total de la habilidad es +4. Un 11 en el d20 da 15. Si no eres competente, normalmente usas +2 y ese mismo dado da 13. Si una capacidad te concede pericia aplicable, el bonificador sería +6. No sumes otra vez lo que ya incluye la hoja.\n\nLímites y diferencias\nNo lee pensamientos ni funciona como un detector infalible de mentiras. Recibes una impresión o información que el DM determina a partir de las señales disponibles.\n\nCómo elegir y usar la ayuda\nPuede ser útil si quieres comprender a otros personajes y tomar decisiones durante conversaciones. En el formulario, marcar Perspicacia gasta una de las elecciones disponibles del grupo. Las competencias concedidas por raza o trasfondo se registran aparte. El icono de ayuda explica la habilidad sin marcarla; Saber más abre este tema y Volver conserva tu selección.'),
  TutorialTopic(
      'skill-intimidacion',
      'Intimidación',
      'Ejercer presión mediante amenazas o una presencia intimidante. Característica habitual: CAR.',
      'Qué representa\nSe utiliza al intentar influir a través del miedo o la presión que describes en una situación concreta. Su característica habitual es CAR. La habilidad describe una tarea; tener competencia indica preparación en esa tarea.\n\nUna escena de ejemplo\nUn saqueador bloquea la salida de una posada. Dices que le exiges apartarse y explicas qué amenaza percibe. El DM puede pedir Intimidación si existe una posibilidad razonable de influir. Primero describe lo que quieres conseguir y cómo lo intentas; el DM decide si necesitas dados.\n\nCómo leer el bonificador\nCon CAR 14 tienes modificador +2. En nivel 1, si eres competente en Intimidación, añades competencia +2: el total de la habilidad es +4. Un 11 en el d20 da 15. Si no eres competente, normalmente usas +2 y ese mismo dado da 13. Si una capacidad te concede pericia aplicable, el bonificador sería +6. No sumes otra vez lo que ya incluye la hoja.\n\nLímites y diferencias\nNo convierte a alguien en aliado ni garantiza obediencia. Puede provocar resistencia, alarma o consecuencias posteriores. Acordad límites antes de representar amenazas entre personajes jugadores.\n\nCómo elegir y usar la ayuda\nPuede encajar con una presencia firme; no depende únicamente del tamaño del personaje. En el formulario, marcar Intimidación gasta una de las elecciones disponibles del grupo. Las competencias concedidas por raza o trasfondo se registran aparte. El icono de ayuda explica la habilidad sin marcarla; Saber más abre este tema y Volver conserva tu selección.'),
  TutorialTopic(
      'skill-investigacion',
      'Investigación',
      'Analizar pistas y deducir cómo encajan. Característica habitual: INT.',
      'Qué representa\nRepresenta razonamiento al examinar información y buscar una explicación coherente. Su característica habitual es INT. La habilidad describe una tarea; tener competencia indica preparación en esa tarea.\n\nUna escena de ejemplo\nEncuentras marcas en una ventana y muebles movidos. Dices que comparas las señales para entender por dónde entró alguien. El DM puede pedir Investigación. Primero describe lo que quieres conseguir y cómo lo intentas; el DM decide si necesitas dados.\n\nCómo leer el bonificador\nCon INT 14 tienes modificador +2. En nivel 1, si eres competente en Investigación, añades competencia +2: el total de la habilidad es +4. Un 11 en el d20 da 15. Si no eres competente, normalmente usas +2 y ese mismo dado da 13. Si una capacidad te concede pericia aplicable, el bonificador sería +6. No sumes otra vez lo que ya incluye la hoja.\n\nLímites y diferencias\nPercepción se centra en advertir señales; Investigación, en analizarlas. Describe tu método: no puedes deducir información que no has encontrado o que no resulta accesible.\n\nCómo elegir y usar la ayuda\nPuede ser útil en misterios, búsquedas cuidadosas y al estudiar mecanismos o indicios. En el formulario, marcar Investigación gasta una de las elecciones disponibles del grupo. Las competencias concedidas por raza o trasfondo se registran aparte. El icono de ayuda explica la habilidad sin marcarla; Saber más abre este tema y Volver conserva tu selección.'),
  TutorialTopic(
      'skill-medicina',
      'Medicina',
      'Atención y valoración de situaciones médicas. Característica habitual: SAB.',
      'Qué representa\nSe relaciona con reconocer problemas de salud y prestar la ayuda que permiten las reglas y las circunstancias. Su característica habitual es SAB. La habilidad describe una tarea; tener competencia indica preparación en esa tarea.\n\nUna escena de ejemplo\nUn mensajero se desploma durante una marcha. Explicas que lo examinas y buscas señales de qué le ocurre. El DM puede pedir Medicina para determinar qué adviertes. Primero describe lo que quieres conseguir y cómo lo intentas; el DM decide si necesitas dados.\n\nCómo leer el bonificador\nCon SAB 14 tienes modificador +2. En nivel 1, si eres competente en Medicina, añades competencia +2: el total de la habilidad es +4. Un 11 en el d20 da 15. Si no eres competente, normalmente usas +2 y ese mismo dado da 13. Si una capacidad te concede pericia aplicable, el bonificador sería +6. No sumes otra vez lo que ya incluye la hoja.\n\nLímites y diferencias\nNo restaura PG como un conjuro de curación. Estabilizar a una criatura a 0 PG es una acción con reglas específicas; estabilizar no significa recuperar la consciencia.\n\nCómo elegir y usar la ayuda\nPuede encajar con alguien que cuida a otros, aunque no tenga magia curativa. En el formulario, marcar Medicina gasta una de las elecciones disponibles del grupo. Las competencias concedidas por raza o trasfondo se registran aparte. El icono de ayuda explica la habilidad sin marcarla; Saber más abre este tema y Volver conserva tu selección.'),
  TutorialTopic(
      'skill-naturaleza',
      'Naturaleza',
      'Conocimientos sobre el mundo natural. Característica habitual: INT.',
      'Qué representa\nRefleja información aprendida sobre organismos, entornos y otros fenómenos de la naturaleza. Su característica habitual es INT. La habilidad describe una tarea; tener competencia indica preparación en esa tarea.\n\nUna escena de ejemplo\nVes plantas poco habituales alrededor de un estanque y preguntas qué recuerdas sobre ellas. El DM puede pedir Naturaleza para determinar la información que conoces. Primero describe lo que quieres conseguir y cómo lo intentas; el DM decide si necesitas dados.\n\nCómo leer el bonificador\nCon INT 14 tienes modificador +2. En nivel 1, si eres competente en Naturaleza, añades competencia +2: el total de la habilidad es +4. Un 11 en el d20 da 15. Si no eres competente, normalmente usas +2 y ese mismo dado da 13. Si una capacidad te concede pericia aplicable, el bonificador sería +6. No sumes otra vez lo que ya incluye la hoja.\n\nLímites y diferencias\nConocer un entorno no sustituye orientarte, rastrear o manejar un animal. Esas tareas pueden requerir Supervivencia o Trato con animales según tu intención.\n\nCómo elegir y usar la ayuda\nPuede ayudar a un personaje curioso por paisajes, plantas y criaturas del mundo. En el formulario, marcar Naturaleza gasta una de las elecciones disponibles del grupo. Las competencias concedidas por raza o trasfondo se registran aparte. El icono de ayuda explica la habilidad sin marcarla; Saber más abre este tema y Volver conserva tu selección.'),
  TutorialTopic(
      'skill-percepcion',
      'Percepción',
      'Advertir señales del entorno mediante los sentidos. Característica habitual: SAB.',
      'Qué representa\nSe utiliza cuando intentas notar algo que puede pasar inadvertido en las circunstancias de la escena. Su característica habitual es SAB. La habilidad describe una tarea; tener competencia indica preparación en esa tarea.\n\nUna escena de ejemplo\nAntes de abrir una puerta, dices que te detienes a escuchar. El DM puede pedir Percepción para determinar si adviertes algo al otro lado. Primero describe lo que quieres conseguir y cómo lo intentas; el DM decide si necesitas dados.\n\nCómo leer el bonificador\nCon SAB 14 tienes modificador +2. En nivel 1, si eres competente en Percepción, añades competencia +2: el total de la habilidad es +4. Un 11 en el d20 da 15. Si no eres competente, normalmente usas +2 y ese mismo dado da 13. Si una capacidad te concede pericia aplicable, el bonificador sería +6. No sumes otra vez lo que ya incluye la hoja.\n\nLímites y diferencias\nNo atraviesa obstáculos ni revela información inaccesible a tus sentidos. Si observas una pista, analizar su significado puede necesitar otro paso.\n\nCómo elegir y usar la ayuda\nTambién puede intervenir la percepción pasiva: normalmente 10 más tu bonificador de Percepción, antes de otros efectos. En el formulario, marcar Percepción gasta una de las elecciones disponibles del grupo. Las competencias concedidas por raza o trasfondo se registran aparte. El icono de ayuda explica la habilidad sin marcarla; Saber más abre este tema y Volver conserva tu selección.'),
  TutorialTopic(
      'skill-interpretacion',
      'Interpretación',
      'Transmitir una actuación a un público. Característica habitual: CAR.',
      'Qué representa\nSe relaciona con la expresión y la ejecución de una actuación cuando su resultado tiene importancia. Su característica habitual es CAR. La habilidad describe una tarea; tener competencia indica preparación en esa tarea.\n\nUna escena de ejemplo\nEn una celebración presentas una canción de viaje y describes cómo intentas captar la atención de los asistentes. El DM puede pedir Interpretación. Primero describe lo que quieres conseguir y cómo lo intentas; el DM decide si necesitas dados.\n\nCómo leer el bonificador\nCon CAR 14 tienes modificador +2. En nivel 1, si eres competente en Interpretación, añades competencia +2: el total de la habilidad es +4. Un 11 en el d20 da 15. Si no eres competente, normalmente usas +2 y ese mismo dado da 13. Si una capacidad te concede pericia aplicable, el bonificador sería +6. No sumes otra vez lo que ya incluye la hoja.\n\nLímites y diferencias\nActuar bien no obliga a un público a aceptar una petición. La competencia con un instrumento es distinta de la habilidad y el DM decide qué aplica a la prueba.\n\nCómo elegir y usar la ayuda\nPuede encajar con música, narración, danza u otras actuaciones de tu personaje. En el formulario, marcar Interpretación gasta una de las elecciones disponibles del grupo. Las competencias concedidas por raza o trasfondo se registran aparte. El icono de ayuda explica la habilidad sin marcarla; Saber más abre este tema y Volver conserva tu selección.'),
  TutorialTopic(
      'skill-persuasion',
      'Persuasión',
      'Influir con argumentos, tacto o una petición razonable. Característica habitual: CAR.',
      'Qué representa\nRepresenta la capacidad de presentar una propuesta de forma apropiada para la persona y la situación. Su característica habitual es CAR. La habilidad describe una tarea; tener competencia indica preparación en esa tarea.\n\nUna escena de ejemplo\nPides a una artesana que abra su taller para revisar una pieza urgente. Explicas el problema y qué le ofreces a cambio. El DM puede pedir Persuasión. Primero describe lo que quieres conseguir y cómo lo intentas; el DM decide si necesitas dados.\n\nCómo leer el bonificador\nCon CAR 14 tienes modificador +2. En nivel 1, si eres competente en Persuasión, añades competencia +2: el total de la habilidad es +4. Un 11 en el d20 da 15. Si no eres competente, normalmente usas +2 y ese mismo dado da 13. Si una capacidad te concede pericia aplicable, el bonificador sería +6. No sumes otra vez lo que ya incluye la hoja.\n\nLímites y diferencias\nNo es control mental ni garantiza algo que la otra persona nunca aceptaría. Describe el objetivo y tu propuesta, aunque tú no sepas pronunciar un discurso perfecto.\n\nCómo elegir y usar la ayuda\nPuede ser útil en negociaciones, acuerdos y conversaciones donde buscas colaboración. En el formulario, marcar Persuasión gasta una de las elecciones disponibles del grupo. Las competencias concedidas por raza o trasfondo se registran aparte. El icono de ayuda explica la habilidad sin marcarla; Saber más abre este tema y Volver conserva tu selección.'),
  TutorialTopic(
      'skill-religion',
      'Religión',
      'Conocimientos sobre creencias y prácticas religiosas. Característica habitual: INT.',
      'Qué representa\nRefleja lo que tu personaje ha aprendido acerca de tradiciones y símbolos vinculados con la religión. Su característica habitual es INT. La habilidad describe una tarea; tener competencia indica preparación en esa tarea.\n\nUna escena de ejemplo\nEncuentras un altar con un emblema desconocido y preguntas si lo relacionas con alguna tradición que estudiaste. El DM puede pedir Religión. Primero describe lo que quieres conseguir y cómo lo intentas; el DM decide si necesitas dados.\n\nCómo leer el bonificador\nCon INT 14 tienes modificador +2. En nivel 1, si eres competente en Religión, añades competencia +2: el total de la habilidad es +4. Un 11 en el d20 da 15. Si no eres competente, normalmente usas +2 y ese mismo dado da 13. Si una capacidad te concede pericia aplicable, el bonificador sería +6. No sumes otra vez lo que ya incluye la hoja.\n\nLímites y diferencias\nNo te obliga a practicar esa fe ni concede poderes divinos. Saber sobre una ceremonia tampoco implica conocer cualquier secreto de sus participantes.\n\nCómo elegir y usar la ayuda\nPuede encajar con estudios, vida en un templo o interés por las creencias del mundo. En el formulario, marcar Religión gasta una de las elecciones disponibles del grupo. Las competencias concedidas por raza o trasfondo se registran aparte. El icono de ayuda explica la habilidad sin marcarla; Saber más abre este tema y Volver conserva tu selección.'),
  TutorialTopic(
      'skill-juego_manos',
      'Juego de manos',
      'Manipulaciones discretas y precisas con las manos. Característica habitual: DES.',
      'Qué representa\nSe relaciona con mover o manipular algo con destreza cuando importa que el gesto resulte discreto. Su característica habitual es DES. La habilidad describe una tarea; tener competencia indica preparación en esa tarea.\n\nUna escena de ejemplo\nQuieres ocultar una nota pequeña en el pliegue de una manga durante una conversación. Describes cuándo realizas el gesto; el DM puede pedir Juego de manos. Primero describe lo que quieres conseguir y cómo lo intentas; el DM decide si necesitas dados.\n\nCómo leer el bonificador\nCon DES 14 tienes modificador +2. En nivel 1, si eres competente en Juego de manos, añades competencia +2: el total de la habilidad es +4. Un 11 en el d20 da 15. Si no eres competente, normalmente usas +2 y ese mismo dado da 13. Si una capacidad te concede pericia aplicable, el bonificador sería +6. No sumes otra vez lo que ya incluye la hoja.\n\nLímites y diferencias\nNo sustituye automáticamente herramientas de ladrón para cerraduras o trampas, ni Sigilo para esconder todo tu cuerpo. Debe existir una oportunidad de intentar el gesto.\n\nCómo elegir y usar la ayuda\nPuede servir a un personaje hábil con movimientos manuales y pequeñas distracciones. En el formulario, marcar Juego de manos gasta una de las elecciones disponibles del grupo. Las competencias concedidas por raza o trasfondo se registran aparte. El icono de ayuda explica la habilidad sin marcarla; Saber más abre este tema y Volver conserva tu selección.'),
  TutorialTopic(
      'skill-sigilo',
      'Sigilo',
      'Moverte o actuar intentando pasar inadvertido. Característica habitual: DES.',
      'Qué representa\nSe utiliza cuando describes un intento de ocultarte o reducir las señales que pueden delatarte. Su característica habitual es DES. La habilidad describe una tarea; tener competencia indica preparación en esa tarea.\n\nUna escena de ejemplo\nCruzas un patio cuando una patrulla pasa al otro lado de un muro. Explicas dónde buscas cobertura y cómo reduces el ruido. El DM puede pedir Sigilo. Primero describe lo que quieres conseguir y cómo lo intentas; el DM decide si necesitas dados.\n\nCómo leer el bonificador\nCon DES 14 tienes modificador +2. En nivel 1, si eres competente en Sigilo, añades competencia +2: el total de la habilidad es +4. Un 11 en el d20 da 15. Si no eres competente, normalmente usas +2 y ese mismo dado da 13. Si una capacidad te concede pericia aplicable, el bonificador sería +6. No sumes otra vez lo que ya incluye la hoja.\n\nLímites y diferencias\nNo te hace invisible. La luz, los sonidos y la cobertura importan; no siempre puedes ocultarte delante de alguien que te ve con claridad.\n\nCómo elegir y usar la ayuda\nPuede ser útil para exploración discreta, evitando asumir que toda escena necesita esconderse. En el formulario, marcar Sigilo gasta una de las elecciones disponibles del grupo. Las competencias concedidas por raza o trasfondo se registran aparte. El icono de ayuda explica la habilidad sin marcarla; Saber más abre este tema y Volver conserva tu selección.'),
  TutorialTopic(
      'skill-supervivencia',
      'Supervivencia',
      'Resolver necesidades prácticas durante viajes y exploración. Característica habitual: SAB.',
      'Qué representa\nSe relaciona con tomar decisiones prácticas en un entorno, según las señales y recursos disponibles. Su característica habitual es SAB. La habilidad describe una tarea; tener competencia indica preparación en esa tarea.\n\nUna escena de ejemplo\nTras una lluvia buscas por dónde continuó una caravana. Describes que examinas el barro y las huellas antes de seguir. El DM puede pedir Supervivencia. Primero describe lo que quieres conseguir y cómo lo intentas; el DM decide si necesitas dados.\n\nCómo leer el bonificador\nCon SAB 14 tienes modificador +2. En nivel 1, si eres competente en Supervivencia, añades competencia +2: el total de la habilidad es +4. Un 11 en el d20 da 15. Si no eres competente, normalmente usas +2 y ese mismo dado da 13. Si una capacidad te concede pericia aplicable, el bonificador sería +6. No sumes otra vez lo que ya incluye la hoja.\n\nLímites y diferencias\nNo garantiza comida, refugio o una ruta segura en cualquier lugar. Conocer datos sobre una especie o un paisaje puede requerir Naturaleza.\n\nCómo elegir y usar la ayuda\nPuede encajar con rastreo, orientación y aventuras en espacios naturales. En el formulario, marcar Supervivencia gasta una de las elecciones disponibles del grupo. Las competencias concedidas por raza o trasfondo se registran aparte. El icono de ayuda explica la habilidad sin marcarla; Saber más abre este tema y Volver conserva tu selección.'),
  TutorialTopic(
      'expertise',
      'Pericia',
      'Duplica el bonificador de competencia en las pruebas que cubre tu capacidad; no duplica el modificador del atributo.',
      'Qué significa pericia\nEs una capacidad que mejora ciertas competencias cuando sus reglas lo permiten. No es otra habilidad ni una puntuación adicional de característica. Lee qué pruebas cubre la capacidad concreta.\n\nEjemplo con Sigilo\nCon DES 14 el modificador es +2. En nivel 1 la competencia es +2: ser competente en Sigilo da +4. Si eliges pericia aplicable a Sigilo, duplicas solo la competencia: +2 de DES y +4 de competencia dan +6. No duplicas el dado ni añades competencia una tercera vez.\n\nQué elige el pícaro en este asistente\nEn nivel 1 elige dos de sus habilidades competentes, o una de ellas y herramientas de ladrón. No puedes elegir pericia en una habilidad en la que no eres competente. Haber recibido la misma competencia de dos orígenes no concede pericia automáticamente.\n\nEn la aplicación\nEl grupo Pericia muestra las elecciones disponibles después de registrar tus competencias. Cambiar una competencia puede obligarte a volver a elegir pericias. Cada habilidad tiene su propia ayuda y las herramientas de ladrón tienen una explicación separada.'),
  TutorialTopic(
      'tool-thieves-tools',
      'Herramientas de ladrón',
      'Utensilios para trabajar con cerraduras y trampas; su competencia es distinta de Juego de manos.',
      'Qué son estas herramientas\nSon un conjunto de utensilios para tareas propias de cerraduras y trampas. Son herramientas, no una de las 18 habilidades. Disponer del objeto, ser competente con él y tener pericia son cosas distintas.\n\nUna escena de ejemplo\nEncuentras un cofre cerrado. Dices que examinas el cierre y explicas cómo intentarías abrirlo con tus herramientas. El DM decide si puedes intentarlo, qué característica corresponde y qué condiciones exige la cerradura. No se abre automáticamente por estar en el inventario.\n\nCómo se calcula una prueba\nSi la prueba utiliza DES, con DES 14 tienes +2. Cuando tu competencia con las herramientas sea aplicable en nivel 1, añades +2: total +4. Con pericia aplicable, la competencia se duplica y da +6. La característica y los requisitos dependen de la tarea y sus reglas.\n\nDiferencia con otras habilidades\nJuego de manos describe gestos discretos con las manos; Investigación puede ayudar a estudiar un mecanismo. Ninguna reemplaza por sí sola todas las tareas de estas herramientas. Describe los pasos de tu intento en lugar de elegir simplemente el mayor bonificador.\n\nEn la aplicación\nEl pícaro puede escoger herramientas de ladrón como una de sus opciones de pericia de nivel 1. Debes completar el equipo con el DM y anotar que llevas las herramientas; seleccionar pericia no añade el objeto al inventario.'),
  TutorialTopic(
      'milestones',
      'Hitos y Experiencia (XP)',
      'El progreso de los aventureros se gestiona mediante hitos narrativos o experiencia dentro de una campaña activa.',
      'Progresión en Campaña\nEn D&D 5e la subida de nivel de un aventurero refleja sus vivencias y logros compartidos. En LA CRIPTA, un personaje no puede subir de nivel si no forma parte de una campaña activa.\n\nHitos de Campaña (Milestones)\nEl DM define objetivos o hitos narrativos importantes para la historia (como limpiar una mazmorra o derrotar al líder enemigo). Cuando el grupo cumple el objetivo, el DM marca el hito como completado y el sistema otorga a todos los personajes la cantidad exacta de experiencia requerida para alcanzar el nivel objetivo (por ejemplo, 300 XP para Nivel 2, 900 XP para Nivel 3, etc.).\n\nContador de Experiencia y Concesión de XP\nLa experiencia ganada se guarda en la ficha del personaje y se preserva entre campañas. El DM puede también otorgar experiencia manualmente a cada personaje desde el Control de Personajes para reflejar desafíos adicionales o recompensas individuales.\n\nMomento de Subir de Nivel\nUna vez que el personaje reúne la experiencia requerida gracias a los hitos o la asignación del DM, el jugador puede abrir su hoja y confirmar la subida de nivel mediante el asistente guiado.'),
];
TutorialTopic? topicForLabel(String label) {
  final key = label.toLowerCase();
  final id = switch (key) {
    'pericia' => 'expertise',
    'raza' => 'race',
    'subraza' => 'subrace',
    'clase' => 'class',
    'alineamiento' => 'alignment',
    'nombre de la campaña' => 'campaign-name',
    'descripción de la campaña' => 'campaign-description',
    'código de unión' => 'invitation',
    'personaje a usar' => 'join-character',
    'nombre del personaje' ||
    'url de imagen (avatar)' ||
    'apariencia' =>
      'avatar',
    'historia del personaje' ||
    'ideales' ||
    'vínculos' ||
    'defectos' ||
    'trasfondo' =>
      'background',
    'ca' || 'clase de armadura' => 'ac',
    'pg' || 'pg max' || 'pg máx' || 'puntos de golpe' || 'dados de golpe' => 'hp',
    'iniciativa' || 'iniciat' || 'velocidad' => 'initiative',
    'competencias' ||
    'competencias de clase' ||
    'competencias raciales' ||
    'competencias del trasfondo' ||
    'competencia' ||
    'bono competencia' ||
    'bonificador de competencia' ||
    'salvaciones' ||
    'tiradas de salvación' ||
    'habilidades' ||
    'percepción pasiva' =>
      'skills',
    'equipo' ||
    'inventario' ||
    'equipo inicial' ||
    'ataques' ||
    'acciones' ||
    'acciones en combate' =>
      'equipment',
    'conjuros' || 'trucos' || 'conjuros y magia' => 'spells',
    'rasgos' || 'nivel' || 'rasgos de raza y clase' => 'class',
    'historia' || 'descripción física' => 'background',
    'estado de personajes' || 'control de personajes' => 'status',
    'hitos' || 'hitos de campaña' => 'milestones',
    'notas ocultas' => 'notes',
    'fue' || 'fuerza' => 'strength',
    'des' || 'destreza' => 'dexterity',
    'con' || 'constitución' || 'constitucion' => 'constitution',
    'int' || 'inteligencia' => 'intelligence',
    'sab' || 'sabiduría' || 'sabiduria' => 'wisdom',
    'car' || 'carisma' => 'charisma',
    'atributos' || 'características' => 'abilities',
    _ => null,
  };
  for (final topic in tutorialTopics) {
    if (topic.id == id) return topic;
  }
  return null;
}

/// El nombre de una habilidad puede coincidir con un campo narrativo (Historia).
/// Las opciones de competencias se resuelven por su clave, no por su etiqueta.
TutorialTopic? topicForSkill(String key) {
  final id = key == 'thieves_tools' ? 'tool-thieves-tools' : 'skill-$key';
  for (final topic in tutorialTopics) {
    if (topic.id == id) return topic;
  }
  return null;
}
